BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-22802'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='BL0048' OR source_url ~ '[?&]id=22802(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='f874438f-980b-47bd-8211-1b4e88d00048' OR slug='sam-direct-sale-factory-huai-khwang-mueang-chonburi-bl0048' OR description ILIKE '%BL0048%' OR (abs(latitude-13.26299)<0.0001 AND abs(longitude-100.954485)<0.0001 AND abs(land_area_sqm-1624)<1)) THEN RAISE NOTICE 'SAM BL0048 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, custom_unit_number, title, description, sale_price, price_negotiable, land_area_sqm, total_floors, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('f874438f-980b-47bd-8211-1b4e88d00048', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'factory', 'business', 'sale', 'whole_property', '21/35', 'ขายตรง SAM โรงงาน/โกดัง ถนนห้วยขวาง ชลบุรี ที่ดิน 1 ไร่ 6 ตร.ว.', 'โรงงานชั้นเดียว เลขที่ 21/35 ถนนห้วยขวาง ตำบลเหมือง อำเภอเมืองชลบุรี จังหวัดชลบุรี บนที่ดิน 2 แปลงติดต่อกัน โฉนดเลขที่ 80176 และ 184671 จำนวน 2 ฉบับ เนื้อที่ 1 ไร่ 6 ตร.ว. หรือ 406 ตร.ว. (1,624 ตร.ม.) ราคาประกาศขายจาก SAM 6,535,000 บาท รหัสทรัพย์ BL0048

ที่ดินรูปสามเหลี่ยม ด้านทิศใต้ติดถนนกว้างประมาณ 42 เมตร ลึกสุดตามแนวติดทางรถไฟสายฉะเชิงเทรา–สัตหีบประมาณ 113 เมตร ถนนหน้าทรัพย์คือถนนห้วยขวาง เป็นทางสาธารณประโยชน์ ผิวคอนกรีตกว้างประมาณ 6 เมตร เขตทางประมาณ 8 เมตร ควรตรวจแนวเขตด้านทางรถไฟและพื้นที่สำหรับรถที่ต้องการใช้งาน

รายการสิ่งปลูกสร้างที่ต้องตรวจสอบ: SAM รับโอนโรงงานเลขที่ 21/35 ห้องน้ำ และโรงจอดรถ 2 รายการ แต่ข้อมูลสำรวจพบโรงงานชั้นเดียว ห้องน้ำชั้นเดียว และโรงจอดรถชั้นเดียวหลังที่ 1 ผังอาคารต้นทางระบุอาคาร ค.ส.ล. ชั้นเดียวและโรงจอดรถหลังที่ 2 ว่ารื้อถอนแล้ว SAM ระบุว่าจะโอนตามรายการสิ่งปลูกสร้างที่จดทะเบียนรับโอนเท่านั้น ผู้ซื้อควรตรวจสภาพจริง รายการโอน และเอกสารรื้อถอน โดยไม่ถือว่าอาคารทุกรายการยังคงอยู่

ต้นทางระบุผังเมืองสีส้ม ย่านที่อยู่อาศัยและอุตสาหกรรม พร้อมสาธารณูปโภคตามข้อมูล SAM สถานที่ใกล้เคียง ได้แก่ ศูนย์ปรับปรุงคุณภาพปฏิกูล ตลาดพรประเสริฐ และโรงเรียนพระอริยะธรรมบาลี การใช้เป็นโรงงานต้องตรวจใบอนุญาตและข้อกำหนดของกิจการที่ต้องการก่อนซื้อ

การเดินทางตาม SAM: ใช้ถนนเลี่ยงเมืองหนองมนจากถนนข้ามหลามมุ่งหน้าถนนสุขุมวิท ผ่านแยกถนนแสนสุขและทางเข้าสำนักเรียนพระอริยธรรมบาลี เลี้ยวซ้ายถนนห้วยขวางประมาณ 1.5 กิโลเมตร ทรัพย์อยู่ด้านซ้ายมือ

ภาพอาคารและภายในแสดงวันที่ 8 กุมภาพันธ์ 2569 รวม 17 ภาพ มีภาพโรงงาน ภายใน โรงจอดรถ ห้องประกอบ พื้นที่รอบแปลง ผังอาคารและแผนที่ ภาพห้องประกอบมีแผ่นวัสดุฝ้าหลุดตกบนพื้นและพื้นที่ภายนอกมีวัชพืช ควรตรวจหลังคา ฝ้า โครงสร้าง ระบบไฟฟ้าและสภาพปัจจุบันก่อนซื้อ

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส BL0048 เพื่อยืนยันสถานะพร้อมขาย ราคา การนัดชม รายการอาคารและเงื่อนไขล่าสุด

พิกัด 13.262990, 100.954485 ดึงจากลิงก์นำทาง SAM และตรงกับ Google Map ต้นทางไม่ระบุพื้นที่ใช้สอยรวมที่ยืนยันแล้ว ความสูงเป็นเมตร น้ำหนักบรรทุกพื้น กำลังไฟฟ้า ใบอนุญาตโรงงาน เครื่องจักรที่รวมขาย ขนาดรถที่รองรับ อายุอาคาร หรือสถานะผู้ครอบครอง จึงต้องยืนยันข้อมูลเหล่านี้กับ SAM', 6535000, false, 1624, 1, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, '21/35 ถนนห้วยขวาง', 'เข้าจากถนนเลี่ยงเมืองหนองมนประมาณ 1.5 กิโลเมตร', 'ถนนห้วยขวาง', 13.26299, 100.954485, 'ชลบุรี', 'เมืองชลบุรี', 'เหมือง', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-factory-huai-khwang-mueang-chonburi-bl0048') RETURNING id INTO property_listing_id;
