INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=22802&keyref=6007684', 'BL0048', now(), 'Official source captured 2026-09-11. THB 6,535,000; 406 sq.wah; factory 21/35. Registered/surveyed inventory difference and plan-demolished RC building/carport 2 disclosed. Registered inventory governs transfer. Railway boundary disclosed. Seventeen source images dated 2026-02-08. Navigation/map agree. All-status duplicate search no matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: Huai Khwang Factory, 406 Sq.Wah, THB 6.535M', 'Single-storey factory numbered 21/35 on Huai Khwang Road, Mueang subdistrict, Mueang Chon Buri district, Chon Buri. Two adjoining Chanote plots, 80176 and 184671, total 406 sq.wah (1,624 sq.m.). SAM announced price THB 6,535,000; asset BL0048.

Triangular land with approximately 42 metres of southern road frontage and maximum depth approximately 113 metres along the Chachoengsao–Sattahip railway boundary. Huai Khwang Road is public, with approximately six metres of concrete carriageway and eight metres right of way. Verify the railway-side boundary and suitability for intended vehicles.

Registered acquisition lists the factory, bathroom and two carports. The survey lists a single-storey factory, bathroom building and carport 1. The source building plan marks a single-storey reinforced-concrete building and carport 2 as demolished. SAM states that transfer follows only its registered acquisition schedule. Verify actual surviving structures, transfer inventory and demolition documents; not all listed structures are represented as still standing.

SAM reports orange zoning, residential/industrial surroundings and available utilities. Nearby places include a sanitation treatment facility, Phon Prasoet Market and Phra Ariya Tham Bali School. Verify licences and requirements for the intended industrial activity.

From Khao Lam Road toward Sukhumvit on Nong Mon bypass, pass Saen Suk intersection and the Buddhist school entrance, turn left into Huai Khwang Road for approximately 1.5 kilometres; the property is on the left.

Building/interior photos display 8 February 2026. Seventeen images include factory, interiors, carport, ancillary rooms, grounds, plans and map. Ancillary rooms show fallen ceiling panels and the grounds have vegetation. Inspect current roof, ceilings, structure and electrical systems.

SAM showed direct purchase and this price on 11 September 2026. Contact 02-686-1888, sales@sam.or.th or LINE @samline, quoting BL0048, to confirm availability, price, viewing, buildings and terms.

Navigation and map agree on 13.262990, 100.954485. Confirmed total usable area, height in metres, floor loading, electrical capacity, factory licence, included machinery, vehicle size, age and occupancy are not published; verify with SAM.', '21/35, Huai Khwang Road', 'Approx. 1.5 km from Nong Mon bypass', 'Huai Khwang Road', 'Mueang', 'Mueang Chon Buri', 'Chon Buri', 'SAM Huai Khwang Factory — THB 6.535M', 'SAM BL0048: factory on 406 sq.wah, Huai Khwang Road, Chon Buri, THB 6,535,000. Railway boundary and building inventory differences disclosed.', 'published', 'ai_assisted', now(), 'sam direct sale: huai khwang factory, 406 sq.wah, thb 6.535m single-storey factory numbered 21/35 on huai khwang road, mueang subdistrict, mueang chon buri district, chon buri. two adjoining chanote plots, 80176 and 184671, total 406 sq.wah (1,624 sq.m.). sam announced price thb 6,535,000; asset bl0048.

triangular land with approximately 42 metres of southern road frontage and maximum depth approximately 113 metres along the chachoengsao–sattahip railway boundary. huai khwang road is public, with approximately six metres of concrete carriageway and eight metres right of way. verify the railway-side boundary and suitability for intended vehicles.

registered acquisition lists the factory, bathroom and two carports. the survey lists a single-storey factory, bathroom building and carport 1. the source building plan marks a single-storey reinforced-concrete building and carport 2 as demolished. sam states that transfer follows only its registered acquisition schedule. verify actual surviving structures, transfer inventory and demolition documents; not all listed structures are represented as still standing.

sam reports orange zoning, residential/industrial surroundings and available utilities. nearby places include a sanitation treatment facility, phon prasoet market and phra ariya tham bali school. verify licences and requirements for the intended industrial activity.

from khao lam road toward sukhumvit on nong mon bypass, pass saen suk intersection and the buddhist school entrance, turn left into huai khwang road for approximately 1.5 kilometres; the property is on the left.

building/interior photos display 8 february 2026. seventeen images include factory, interiors, carport, ancillary rooms, grounds, plans and map. ancillary rooms show fallen ceiling panels and the grounds have vegetation. inspect current roof, ceilings, structure and electrical systems.

sam showed direct purchase and this price on 11 september 2026. contact 02-686-1888, sales@sam.or.th or line @samline, quoting bl0048, to confirm availability, price, viewing, buildings and terms.

navigation and map agree on 13.262990, 100.954485. confirmed total usable area, height in metres, floor loading, electrical capacity, factory licence, included machinery, vehicle size, age and occupancy are not published; verify with sam.') ;
